<template><q-page class="q-pa-lg"><div class="text-overline text-primary">ANALYTICS</div><div class="page-title">Reports & Analytics</div><p class="muted">Real-time insights from your organization's data.</p><q-card flat bordered class="q-mt-md"><q-card-section class="row items-center q-col-gutter-md"><div class="col-12 col-md-2"><q-input v-model="filters.start_date" type="date" outlined dense label="Start date"/></div><div class="col-12 col-md-2"><q-input v-model="filters.end_date" type="date" outlined dense label="End date"/></div><div class="col-12 col-md-2"><q-select v-model="filters.department_id" :options="departments" option-value="id" option-label="name" outlined dense clearable label="Department" emit-value map-options/></div><div class="col-12 col-md-2"><q-select v-model="filters.employee_id" :options="employees" option-value="id" option-label="employee_name" outlined dense clearable label="Employee" emit-value map-options/></div><div class="col-12 col-md-2"><q-select v-model="filters.task_status" :options="taskStatuses" outlined dense clearable label="Task status" emit-value map-options/></div><div class="col-12 col-md-2 row q-gutter-sm"><q-btn color="primary" unelevated label="Apply" :loading="loading" @click="applyFilters"/><q-btn flat label="Reset" @click="resetFilters"/></div></q-card-section></q-card><div v-if="loading" class="text-center q-pa-xl"><q-spinner color="primary" size="40px"/></div><template v-else><div class="row q-col-gutter-lg q-mt-md"><div class="col-12 col-md-4"><q-card flat bordered class="stat-card"><q-card-section><div class="text-subtitle2 text-weight-bold">Employees</div><div class="row q-col-gutter-sm q-mt-sm"><div class="col-6"><div class="text-h5 text-weight-bold">{{summary.employees.total}}</div><div class="text-caption muted">Total</div></div><div class="col-6"><div class="text-h5 text-weight-bold text-positive">{{summary.employees.active}}</div><div class="text-caption muted">Active</div></div><div class="col-6"><div class="text-h5 text-weight-bold text-negative">{{summary.employees.inactive}}</div><div class="text-caption muted">Inactive</div></div><div class="col-6"><div class="text-h5 text-weight-bold">{{summary.employees.departments}}</div><div class="text-caption muted">Departments</div></div></div></q-card-section></q-card></div><div class="col-12 col-md-4"><q-card flat bordered class="stat-card"><q-card-section><div class="text-subtitle2 text-weight-bold">Tasks</div><div class="row q-col-gutter-sm q-mt-sm"><div class="col-6"><div class="text-h5 text-weight-bold">{{summary.tasks.total}}</div><div class="text-caption muted">Total</div></div><div class="col-6"><div class="text-h5 text-weight-bold text-positive">{{summary.tasks.completed}}</div><div class="text-caption muted">Completed</div></div><div class="col-6"><div class="text-h5 text-weight-bold text-primary">{{summary.tasks.inProgress}}</div><div class="text-caption muted">In Progress</div></div><div class="col-6"><div class="text-h5 text-weight-bold text-negative">{{summary.tasks.overdue}}</div><div class="text-caption muted">Overdue</div></div></div></q-card-section></q-card></div><div class="col-12 col-md-4"><q-card flat bordered class="stat-card"><q-card-section><div class="text-subtitle2 text-weight-bold">Leave Requests</div><div class="row q-col-gutter-sm q-mt-sm"><div class="col-6"><div class="text-h5 text-weight-bold">{{summary.leaves.total}}</div><div class="text-caption muted">Total</div></div><div class="col-6"><div class="text-h5 text-weight-bold text-positive">{{summary.leaves.approved}}</div><div class="text-caption muted">Approved</div></div><div class="col-6"><div class="text-h5 text-weight-bold text-negative">{{summary.leaves.rejected}}</div><div class="text-caption muted">Rejected</div></div><div class="col-6"><div class="text-h5 text-weight-bold text-orange">{{summary.leaves.pending}}</div><div class="text-caption muted">Pending</div></div></div></q-card-section></q-card></div></div><div class="row q-col-gutter-lg q-mt-lg"><div class="col-12 col-lg-6"><q-card flat bordered><q-card-section class="text-h6">Task Status Distribution</q-card-section><q-separator/><q-card-section v-if="hasTaskData"><Doughnut :data="taskStatusChart" :options="chartOptions"/></q-card-section><q-card-section v-else class="text-center q-pa-xl"><q-icon name="pie_chart" size="48px" color="indigo-3"/><div class="text-h6 q-mt-sm">No task data</div><div class="muted">Tasks will appear here.</div></q-card-section></q-card></div><div class="col-12 col-lg-6"><q-card flat bordered><q-card-section class="text-h6">Tasks by Employee</q-card-section><q-separator/><q-card-section v-if="hasTaskData"><Bar :data="tasksByEmployeeChart" :options="barOptions"/></q-card-section><q-card-section v-else class="text-center q-pa-xl"><q-icon name="bar_chart" size="48px" color="indigo-3"/><div class="text-h6 q-mt-sm">No task data</div><div class="muted">Tasks will appear here.</div></q-card-section></q-card></div><div class="col-12 col-lg-6"><q-card flat bordered><q-card-section class="text-h6">Leave Request Status</q-card-section><q-separator/><q-card-section v-if="hasLeaveData"><Doughnut :data="leaveStatusChart" :options="chartOptions"/></q-card-section><q-card-section v-else class="text-center q-pa-xl"><q-icon name="pie_chart" size="48px" color="indigo-3"/><div class="text-h6 q-mt-sm">No leave data</div><div class="muted">Leave requests will appear here.</div></q-card-section></q-card></div><div class="col-12 col-lg-6"><q-card flat bordered><q-card-section class="text-h6">Employees by Department</q-card-section><q-separator/><q-card-section v-if="hasDeptData"><Bar :data="employeesByDeptChart" :options="barOptions"/></q-card-section><q-card-section v-else class="text-center q-pa-xl"><q-icon name="bar_chart" size="48px" color="indigo-3"/><div class="text-h6 q-mt-sm">No department data</div><div class="muted">Departments will appear here.</div></q-card-section></q-card></div></div><q-card flat bordered class="q-mt-lg"><q-tabs v-model="tab" class="text-primary"><q-tab name="employees" label="Employee Report"/><q-tab name="tasks" label="Task Report"/><q-tab name="leaves" label="Leave Report"/></q-tabs><q-separator/><q-tab-panels v-model="tab" animated><q-tab-panel name="employees"><div class="row items-center q-mb-md"><div class="text-subtitle1 text-weight-bold">Employee Report</div><q-space/><q-btn flat color="primary" icon="download" label="Export CSV" :loading="exporting" @click="exportCSV('employees')"/></div><q-table :rows="employeeRows" :columns="employeeCols" row-key="id" :loading="tableLoading" flat><template #body-cell-is_active="p"><q-td><q-badge :color="p.row.is_active?'positive':'grey-6'" :label="p.row.is_active?'Active':'Inactive'"/></q-td></template></q-table></q-tab-panel><q-tab-panel name="tasks"><div class="row items-center q-mb-md"><div class="text-subtitle1 text-weight-bold">Task Report</div><q-space/><q-btn flat color="primary" icon="download" label="Export CSV" :loading="exporting" @click="exportCSV('tasks')"/></div><q-table :rows="taskRows" :columns="taskCols" row-key="id" :loading="tableLoading" flat><template #body-cell-status="p"><q-td><q-badge :color="statusColor(p.row.status)" :label="p.row.status"/></q-td></template><template #body-cell-priority="p"><q-td><q-badge :color="priorityColor(p.row.priority)" :label="p.row.priority"/></q-td></template></q-table></q-tab-panel><q-tab-panel name="leaves"><div class="row items-center q-mb-md"><div class="text-subtitle1 text-weight-bold">Leave Report</div><q-space/><q-btn flat color="primary" icon="download" label="Export CSV" :loading="exporting" @click="exportCSV('leaves')"/></div><q-table :rows="leaveRows" :columns="leaveCols" row-key="id" :loading="tableLoading" flat><template #body-cell-status="p"><q-td><q-badge :color="leaveStatusColor(p.row.status)" :label="p.row.status"/></q-td></template></q-table></q-tab-panel></q-tab-panels></q-card></template></q-page></template>
<script setup>import {ref,computed,onMounted} from 'vue';import {useQuasar} from 'quasar';import {Doughnut,Bar} from 'vue-chartjs';import {Chart as ChartJS,ArcElement,BarElement,CategoryScale,LinearScale,Tooltip,Legend} from 'chart.js';import api from '../services/api';ChartJS.register(ArcElement,BarElement,CategoryScale,LinearScale,Tooltip,Legend);const $q=useQuasar(),loading=ref(false),tableLoading=ref(false),exporting=ref(false),tab=ref('employees'),departments=ref([]),employees=ref([]),summary=ref({employees:{total:0,active:0,inactive:0,departments:0},tasks:{total:0,completed:0,inProgress:0,pending:0,overdue:0},leaves:{total:0,approved:0,rejected:0,pending:0}}),charts=ref({taskStatus:[],overdue:0,tasksByEmployee:[],leaveStatus:[],employeesByDept:[]}),employeeRows=ref([]),taskRows=ref([]),leaveRows=ref([]),filters=ref({start_date:null,end_date:null,department_id:null,employee_id:null,task_status:null}),taskStatuses=[{label:'All Statuses',value:null},{label:'To Do',value:'To Do'},{label:'In Progress',value:'In Progress'},{label:'Completed',value:'Completed'},{label:'Overdue',value:'Overdue'}];const chartOptions={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}};const barOptions={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}};const hasTaskData=computed(()=>charts.value.taskStatus.length>0||charts.value.overdue>0);const hasLeaveData=computed(()=>charts.value.leaveStatus.length>0);const hasDeptData=computed(()=>charts.value.employeesByDept.length>0);const taskStatusChart=computed(()=>{const labels=['To Do','In Progress','Completed','Overdue'];const counts=[0,0,0,0];charts.value.taskStatus.forEach(s=>{const i=labels.indexOf(s.status);if(i>=0)counts[i]=s.count});counts[3]=charts.value.overdue;return{labels,datasets:[{data:counts,backgroundColor:['#ef6c00','#4f46e5','#2e7d32','#c62828'],borderWidth:0}]}});const tasksByEmployeeChart=computed(()=>({labels:charts.value.tasksByEmployee.map(e=>e.employee_name),datasets:[{label:'Assigned',data:charts.value.tasksByEmployee.map(e=>e.total),backgroundColor:'#4f46e5'},{label:'Completed',data:charts.value.tasksByEmployee.map(e=>e.completed),backgroundColor:'#2e7d32'}]}));const leaveStatusChart=computed(()=>{const labels=['Approved','Rejected','Pending'];const counts=[0,0,0];charts.value.leaveStatus.forEach(s=>{const i=labels.indexOf(s.status);if(i>=0)counts[i]=s.count});return{labels,datasets:[{data:counts,backgroundColor:['#2e7d32','#c62828','#ef6c00'],borderWidth:0}]}});const employeesByDeptChart=computed(()=>({labels:charts.value.employeesByDept.map(d=>d.department_name),datasets:[{label:'Employees',data:charts.value.employeesByDept.map(d=>d.count),backgroundColor:'#4f46e5'}]}));const employeeCols=[{name:'employee_name',label:'Employee',field:'employee_name',align:'left'},{name:'email',label:'Email',field:'email',align:'left'},{name:'department_name',label:'Department',field:'department_name'},{name:'role',label:'Role',field:'role'},{name:'is_active',label:'Status',field:'is_active'},{name:'assigned_tasks',label:'Assigned Tasks',field:'assigned_tasks'},{name:'completed_tasks',label:'Completed Tasks',field:'completed_tasks'}];const taskCols=[{name:'title',label:'Task',field:'title',align:'left'},{name:'assigned_name',label:'Assigned To',field:'assigned_name'},{name:'creator_name',label:'Created By',field:'creator_name'},{name:'status',label:'Status',field:'status'},{name:'priority',label:'Priority',field:'priority'},{name:'due_date',label:'Due Date',field:'due_date'},{name:'created_at',label:'Created',field:'created_at'}];const leaveCols=[{name:'employee_name',label:'Employee',field:'employee_name',align:'left'},{name:'leave_type',label:'Leave Type',field:'leave_type'},{name:'start_date',label:'Start',field:'start_date'},{name:'end_date',label:'End',field:'end_date'},{name:'status',label:'Status',field:'status'},{name:'created_at',label:'Requested',field:'created_at'},{name:'reviewer_name',label:'Reviewed By',field:'reviewer_name'}];const statusColor=x=>x==='Completed'?'positive':x==='In Progress'?'primary':'orange';const priorityColor=x=>x==='High'?'negative':x==='Medium'?'orange':'positive';const leaveStatusColor=x=>x==='Approved'?'positive':x==='Rejected'?'negative':x==='Cancelled'?'grey-6':'orange';function params(){const p={};if(filters.value.start_date)p.start_date=filters.value.start_date;if(filters.value.end_date)p.end_date=filters.value.end_date;if(filters.value.department_id)p.department_id=filters.value.department_id;if(filters.value.employee_id)p.employee_id=filters.value.employee_id;if(filters.value.task_status)p.task_status=filters.value.task_status;return p;}async function loadMeta(){try{const r=await api.get('/reports/meta');departments.value=r.data.data.departments;employees.value=r.data.data.employees}catch{}}async function loadAll(){loading.value=true;tableLoading.value=true;try{const p=params();const [s,c,er,tr,lr]=await Promise.all([api.get('/reports/summary',{params:p}),api.get('/reports/charts',{params:p}),api.get('/reports/employees',{params:p}),api.get('/reports/tasks',{params:p}),api.get('/reports/leaves',{params:p})]);summary.value=s.data.data;charts.value=c.data.data;employeeRows.value=er.data.data;taskRows.value=tr.data.data;leaveRows.value=lr.data.data}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Failed to load reports'})}finally{loading.value=false;tableLoading.value=false}}function applyFilters(){loadAll()}function resetFilters(){filters.value={start_date:null,end_date:null,department_id:null,employee_id:null,task_status:null};loadAll()}function escapeCSV(v){if(v===null||v===undefined)return '';const s=String(v);return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;}function exportCSV(type){const map={employees:{rows:employeeRows.value,cols:employeeCols,file:'employee-report.csv'},tasks:{rows:taskRows.value,cols:taskCols,file:'task-report.csv'},leaves:{rows:leaveRows.value,cols:leaveCols,file:'leave-report.csv'}};const cfg=map[type];if(!cfg.rows.length){$q.notify({type:'warning',message:'No data to export'});return}exporting.value=true;try{const header=cfg.cols.map(c=>escapeCSV(c.label)).join(',');const body=cfg.rows.map(r=>cfg.cols.map(c=>escapeCSV(r[c.field])).join(',')).join('\n');const csv=header+'\n'+body;const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=cfg.file;a.click();URL.revokeObjectURL(url);$q.notify({type:'positive',message:`${cfg.file} exported`})}catch(e){$q.notify({type:'negative',message:'Export failed'})}finally{exporting.value=false}}onMounted(()=>{loadMeta();loadAll()})</script>